challenge.solution:
// İki zar at
const dice1 = Math.floor(Math.random() * 6) + 1;
const dice2 = Math.floor(Math.random() * 6) + 1;
const total = dice1 + dice2;

console.log(dice1, "+", dice2, "=", total);

check.js:
const ok = (d) => Number.isInteger(d) && d >= 1 && d <= 6;
assert(ok(dice1) && ok(dice2), "dice1 ve dice2 1 ile 6 arasında tam sayı olmalı.");
assert(total === dice1 + dice2, "total iki zarın toplamı olmalı.");

project_task.starter:
let stars = 7;
const starPoints = 10;

// score ve hasBonus'u hesapla

console.log("Skor:", score, "| Bonus:", hasBonus);

project_task.solution:
let stars = 7;
const starPoints = 10;

// score ve hasBonus'u hesapla
const score = stars * starPoints;
const hasBonus = stars >= 5;

console.log("Skor:", score, "| Bonus:", hasBonus);

check.js:
assert(score === 70, "score 70 olmalı.");
assert(hasBonus === true, "hasBonus true olmalı.");
assert(_lines.includes("Skor: 70 | Bonus: true"), "Çıktıda 'Skor: 70 | Bonus: true' görünmeli.");

project_task.starter:
const weeklyVisits = 1250;
const days = 7;

// dailyAverage ve isPopular'ı hesapla

console.log("Günlük ortalama:", dailyAverage, "| Popüler:", isPopular);

project_task.solution:
const weeklyVisits = 1250;
const days = 7;

// dailyAverage ve isPopular'ı hesapla
const dailyAverage = Math.round(weeklyVisits / days);
const isPopular = dailyAverage > 100;

console.log("Günlük ortalama:", dailyAverage, "| Popüler:", isPopular);

check.js:
assert(dailyAverage === 179, "dailyAverage 179 olmalı (1250 / 7 ≈ 178.57).");
assert(isPopular === true, "isPopular true olmalı.");
assert(_lines.includes("Günlük ortalama: 179 | Popüler: true"), "Çıktıda 'Günlük ortalama: 179 | Popüler: true' görünmeli.");

