project_task.starter:
const correct = 4;
const total = 5;

// percent ve passed'i hesapla

console.log("Başarı:", percent, "| Geçti:", passed);

project_task.solution:
const correct = 4;
const total = 5;

// percent ve passed'i hesapla
const percent = correct / total * 100;
const passed = percent >= 60;

console.log("Başarı:", percent, "| Geçti:", passed);

check.js:
assert(percent === 80, "percent 80 olmalı.");
assert(passed === true, "passed true olmalı.");
assert(_lines.includes("Başarı: 80 | Geçti: true"), "Çıktıda 'Başarı: 80 | Geçti: true' görünmeli.");
